          "mondaiName": "問題10：短文読解 (Đoản văn 1 - Sáng tạo và Tri thức)",
          "passage": "創造力やアイデアの源は、頭の中の記憶の組み合わせから生まれるもので、その土台がしっかりしていなければ、良いアイデアが閃くわけがないのだ。知識は、頭の中に貯えられた記憶の体験が土台になるのである。つまり、知識という基盤がしっかりしていなければ、いくら創造力や企画力を働かせようとしても、うまくいかないのである。",
          "question": "筆者の考えに合うのはどれか。",
