          "passage": "らくらくルーム社　青寺店<br>森田様<br><br>花西マンション302号室に入居予定の木村です。<br>引っ越し当日の3月20日の金曜日、午前中に貴店で新居の鍵を受け取る約束でしたが、荷物が10時に到着することになりました。そのため、前日19日の午後に鍵を受け取りたいと思いホームページを確認したところ、貴店は木曜日が定休日でした。<br>鍵の受け取り日が定休日の場合は、ほかの支店で受け取れると書いてありましたので、仕事帰りに寄れる中央駅前店で受け取りたいのですが、可能でしょうか。<br>お忙しいところ恐縮ですが、ご返信よろしくお願いいたします。<br><br>木村",
