          "passage": "親子はもっとも身近でありながら、ときにもっとも遠くなってしまう存在かもしれない。私も母とは「わかり合えない」と悟ったときに、ある一定の距離ができたことは否めない。だが、そのことで愛情がなくなるとか、関係が冷えるとかそういう感覚は一切なかった。むしろ「わかり合えない」とわかることは相手を理解しようとするための最初の一歩なのではないかと思う。もし「子どものことはなんでも自分が一番よくわかっている」と思っている親がいるとしたら、それはとても怖いことだと思う。",
