          "type": "reading",
          "mondaiName": "問題11：中文読解 (Trung văn 2 - Tâm lý của Chó và Mèo)",
          "passage": "「いぬ」は人間の家畜になる前から、群れで暮らしていた動物です。人間の家族の一員ともなれば集団生活の掟そのままに、飼い主を群れのリーダーや上位のものとみなし、日頃から服従の態度を示します。また、飼い主のその日の顔色を窺うなど、家庭内の空気を読みとりながら、上手にふるまうことにも長けています。群れで生活する動物は、お互いの状況を把握して、それに合わせた行動をとることが、群れ社会のなかで生きていくには必要だからです。人間にとっても、「いぬのきもち」は非常にわかりやすく、会話はできなくとも、お互いなにを考えているかが理解しやすい動物です。そこが、「いぬ」と一緒に暮らすことのひとつの魅力でもあるのでしょう。<br><br>\n一方、「ねこ」は、もともとが単独で行動していた動物ですので、家の中で人間の家族と一緒に暮らすようになっても、協調性のようなものはありません。また、家族の中での自分の立場もあまり気にしないので、いぬのように、飼い主をリーダーとみなして服従することはありません。（中略）ねこがいったい飼い主である自分のことをどう思っているのか、飼い主であれば誰しも知りたいところですが、人間の持つ気持ちや感情の尺度では、完全には理解しがたい動物だと思います。ねこはそもそも集団生活をしない、個を重視する孤独な生き物だからです。しかし、この理解できないところが、ねこの大きな魅力のひとつであり、人間が、ねこと一緒に暮らしたがる理由のひとつではないでしょうか。",
          "question": "筆者によると、ねこを飼う人は、ねこのどんな点がいいと思っているか。",
