          "question": "カールさんは、同じ大学の友人と二人で北原ホテルに泊まりたいと考えている。ベッドがあり、お風呂がついている部屋を選ぶつもりだ。「朝食つきプラン」で日曜日に宿泊する予定だが、希望に合う部屋の一人分の料金はいくらになるか。",
